import re
with open('doc/Patient.md', 'r') as f:
    patient_content = f.read()

# Extract birthdates for all patients with abnormal creatinine
abnormal_patients = ['3182521', '444499', '4634342', '3150681', '2052784', '668398', '2307640', '2395148', '2405722']

patient_birthdates = {}
for pid in abnormal_patients:
    # Find patient section - case insensitive
    start = patient_content.lower().find(f'patient {pid}')
    if start != -1:
        end = patient_content.find('\n\nThe', start)
        if end == -1:
            end = len(patient_content)
        section = patient_content[start:end]

        # Look for various birthdate patterns
        # Pattern 1: "born on the eleventh of November, 1967"
        match = re.search(r'born.*?([A-Za-z]+ \d{1,2},? \d{4})', section, re.IGNORECASE)
        if not match:
            # Pattern 2: "birthdate on the eleventh of November, 1967"
            match = re.search(r'(?:birthdate|birthday).*?([A-Za-z]+ \d{1,2},? \d{4})', section, re.IGNORECASE)
        if not match:
            # Pattern 3: "date of birth recorded as October 3rd, 1947"
            match = re.search(r'date of birth.*?(October|November|December|January|February|March|April|May|June|July|August|September) \d{1,2}(?:st|nd|rd|th)?,? (\d{4})', section, re.IGNORECASE)

        if match:
            patient_birthdates[pid] = match.group(0)[:100]
        else:
            patient_birthdates[pid] = 'Not found'

print('Patient birthdates:')
for pid, bd in patient_birthdates.items():
    print(f'{pid}: {bd}')

